package com.codename1.demos.mazlove;

import com.codename1.ui.*;
import com.codename1.ui.layouts.*;
import com.codename1.ui.plaf.UIManager;
import com.codename1.ui.util.Resources;
import com.codename1.ui.plaf.Style;

/**
 * This file was generated by <a href="https://www.codenameone.com/">Codename One</a> for the purpose 
 * of building native mobile applications using Java.
 */
public class Mazlove {
    private Form current;
    private Resources theme;

    public void init(Object context) {
        // use two network threads instead of one
        updateNetworkThreadCount(2);

        theme = UIManager.initFirstTheme("/theme");
        
        // Enable the status bar across all iOS devices
        if (Display.getInstance().getPlatformName().equals("ios")) {
            Display.getInstance().setProperty("StatusBarColor", "#ffffff");
            Display.getInstance().setProperty("StatusBarStyle", "light");
        }
        
        // Set up the theme with white background and purple accents
        Style s = UIManager.getInstance().getComponentStyle("Label");
        s.setBgColor(0xFFFFFF); // White background
        s.setFgColor(0x6C5CE7); // Purple text
        
        Style buttonStyle = UIManager.getInstance().getComponentStyle("Button");
        buttonStyle.setBgColor(0x6C5CE7); // Purple background
        buttonStyle.setFgColor(0xFFFFFF); // White text
        
        Style headerStyle = UIManager.getInstance().getComponentStyle("TitleCommand");
        headerStyle.setFgColor(0x6C5CE7); // Purple text
        
        Style navBarStyle = UIManager.getInstance().getComponentStyle("Title");
        navBarStyle.setBgColor(0xFFFFFF); // White background
        navBarStyle.setFgColor(0x6C5CE7); // Purple text
        
        // Initialize the app
        initUI();
    }
    
    private void initUI() {
        Form hi = new Form("Mazlove", new BorderLayout());
        hi.getToolbar().setUIID("Container");
        
        // Create a clean, modern UI
        Container contentArea = new Container(new BoxLayout(BoxLayout.Y_AXIS));
        contentArea.setUIID("Container");
        
        // Add a search bar
        TextField searchField = new TextField();
        searchField.setHint("Rechercher un calin...");
        searchField.setUIID("SearchBar");
        contentArea.add(searchField);
        
        // Add filters
        Container filters = new Container(new GridLayout(1, 4));
        filters.setUIID("Container");
        
        Button filterBtn = new Button("Calins");
        filterBtn.setUIID("FilterButton");
        filters.add(filterBtn);
        
        filterBtn = new Button("Durée");
        filterBtn.setUIID("FilterButton");
        filters.add(filterBtn);
        
        filterBtn = new Button("Les mieux notés");
        filterBtn.setUIID("FilterButton");
        filters.add(filterBtn);
        
        filterBtn = new Button("Tr...");
        filterBtn.setUIID("FilterButton");
        filters.add(filterBtn);
        
        contentArea.add(filters);
        
        // Add sponsored content
        Container sponsored = new Container(new BorderLayout());
        sponsored.setUIID("Sponsored");
        
        Label sponsoredTitle = new Label("À découvrir sur Mazlove");
        sponsoredTitle.setUIID("SponsoredTitle");
        
        Label sponsoredText = new Label("Sponsorisé");
        sponsoredText.setUIID("SponsoredText");
        
        sponsored.add(BorderLayout.WEST, sponsoredTitle);
        sponsored.add(BorderLayout.EAST, sponsoredText);
        
        contentArea.add(sponsored);
        
        // Add profiles grid
        Container profiles = new Container(new GridLayout(2, 2));
        profiles.setUIID("ProfilesGrid");
        
        for (int i = 0; i < 4; i++) {
            Container profile = new Container(new BorderLayout());
            profile.setUIID("ProfileCard");
            
            Label name = new Label("Nom " + (i + 1));
            name.setUIID("ProfileName");
            
            Label rating = new Label("★★★★★");
            rating.setUIID("ProfileRating");
            
            Container tags = new Container(new FlowLayout(Component.CENTER));
            tags.setUIID("ProfileTags");
            
            Label tag = new Label("Naturelle");
            tag.setUIID("ProfileTag");
            tags.add(tag);
            
            profile.add(BorderLayout.NORTH, name);
            profile.add(BorderLayout.CENTER, rating);
            profile.add(BorderLayout.SOUTH, tags);
            
            profiles.add(profile);
        }
        
        contentArea.add(profiles);
        
        // Add search button
        Button searchBtn = new Button("Trouver mon calin idéal");
        searchBtn.setUIID("SearchButton");
        contentArea.add(searchBtn);
        
        hi.add(BorderLayout.CENTER, contentArea);
        hi.show();
    }

    public void start() {
        if(current != null){
            current.show();
            return;
        }
        new Mazlove().init(null);
    }

    public void stop() {
        current = Display.getInstance().getCurrent();
    }

    public void destroy() {
    }
}
